"""Write docs/COVERAGE.md: which blocks redsim simulates, from the live block table."""
import collections, json, sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "python"))
from redsim import _redsim

ROOT = Path(__file__).resolve().parents[1]
table = _redsim.blocks_table()
by_kind = collections.defaultdict(list)
for name, first, n, default, kind, props in table:
    by_kind[kind].append(name.split(":", 1)[1])
lines = [f"# Block coverage (Minecraft {_redsim.mc_version()})", "",
         "Generated by `tools/coverage.py` from the simulator's block table.", "",
         "* **Simulated**: the block's redstone/update behaviour is ported from the game and fuzz-tested against it.",
         "* **Static**: the block has no behaviour that can change world state (stone, glass, wool, ...); it still",
         "  has exact conductivity, support faces and piston push rules from the game.",
         "* **Not simulated**: the block reacts in the game but redsim ignores it and records a warning when it",
         "  would have mattered (`World.warnings`).", ""]
static = sorted(by_kind.pop("Plain", []) + by_kind.pop("Air", []))
unsupported = sorted(by_kind.pop("Unsupported", []))
lines.append(f"## Simulated ({sum(len(v) for v in by_kind.values())} blocks)\n")
for kind in sorted(by_kind):
    names = sorted(by_kind[kind])
    lines.append(f"- **{kind}** ({len(names)}): " + ", ".join(names[:40]) + (" ..." if len(names) > 40 else ""))
lines.append(f"\n## Static ({len(static)} blocks)\n")
lines.append(", ".join(static))
lines.append(f"\n## Not simulated yet ({len(unsupported)} blocks)\n")
lines.append(", ".join(unsupported))
lines.append("\nAlso not simulated: entities (item drops, minecarts on detector rails, falling blocks, TNT "
             "explosions, mobs on pressure plates or tripwire, and the vibrations entities make), fluid flow, "
             "dispenser item behaviours, weather (rain darkens daylight detectors), random ticks. Sky light is the settled "
             "value; the game applies light updates on a background thread, so a daylight detector reading light "
             "that changed within the last tick gets a warning.")
(ROOT / "docs" / "COVERAGE.md").write_text("\n".join(lines) + "\n")
print({k: len(v) for k, v in by_kind.items()}, "static", len(static), "unsupported", len(unsupported))
